CREATE INDEX IF NOT EXISTS "idx_token_prices_range" ON "token_prices" USING btree ("chain","token","timestamp");--> statement-breakpoint
CREATE OR REPLACE FUNCTION quarantine_rejected_price() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE rejection_reason TEXT;
BEGIN
  SELECT reason INTO rejection_reason FROM rejected_price_observations
  WHERE chain = NEW.chain AND token = lower(NEW.token)
    AND timestamp = NEW.timestamp AND source = NEW.source;
  IF FOUND THEN
    VALUES (to_jsonb(NEW), rejection_reason);
    RETURN NULL;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
DROP TRIGGER IF EXISTS quarantine_rejected_price ON token_prices;--> statement-breakpoint
CREATE TRIGGER quarantine_rejected_price BEFORE INSERT OR UPDATE ON token_prices FOR EACH ROW EXECUTE FUNCTION quarantine_rejected_price();--> statement-breakpoint
ON CONFLICT DO NOTHING;
